import React, { useMemo, useState } from 'react';
import { Card, Stack, Inline, Button, Text } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  onChange: (date: Date) => void;
  locale?: string;
};

const startOfDay = (d: Date) => new Date(d.getFullYear(), d.getMonth(), d.getDate());

const addDays = (d: Date, days: number) =>
  new Date(d.getFullYear(), d.getMonth(), d.getDate() + days);

const isSameDay = (a: Date | null | undefined, b: Date) =>
  !!a && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

// Календарь строится с понедельника, поэтому воскресенье (0) переносим в конец недели.
const weekdayOffset = (d: Date) => (d.getDay() + 6) % 7;

function buildMonthGrid(year: number, month: number): (Date | null)[] {
  const first = new Date(year, month, 1);
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells: (Date | null)[] = Array(weekdayOffset(first)).fill(null);
  for (let day = 1; day <= daysInMonth; day += 1) cells.push(new Date(year, month, day));
  while (cells.length % 7 !== 0) cells.push(null);
  return cells;
}

function ReportDatePicker({ value = null, onChange, locale = 'ru-RU' }: ReportDatePickerProps) {
  const today = useMemo(() => startOfDay(new Date()), []);
  const [selected, setSelected] = useState<Date | null>(value ? startOfDay(value) : null);
  const [view, setView] = useState(() => {
    const base = value ? startOfDay(value) : today;
    return { year: base.getFullYear(), month: base.getMonth() };
  });

  const current = value ? startOfDay(value) : selected;

  const weekdayNames = useMemo(() => {
    const fmt = new Intl.DateTimeFormat(locale, { weekday: 'short' });
    return Array.from({ length: 7 }, (_, i) => fmt.format(new Date(2024, 0, 1 + i)));
  }, [locale]);

  const monthLabel = useMemo(
    () => new Intl.DateTimeFormat(locale, { month: 'long', year: 'numeric' }).format(new Date(view.year, view.month, 1)),
    [locale, view.year, view.month],
  );

  const cells = useMemo(() => buildMonthGrid(view.year, view.month), [view.year, view.month]);

  const pick = (date: Date) => {
    const next = startOfDay(date);
    setSelected(next);
    setView({ year: next.getFullYear(), month: next.getMonth() });
    onChange(next);
  };

  const shiftMonth = (delta: number) =>
    setView((prev) => {
      const d = new Date(prev.year, prev.month + delta, 1);
      return { year: d.getFullYear(), month: d.getMonth() };
    });

  const presets: { label: string; date: Date }[] = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: addDays(today, -1) },
    { label: 'Неделя назад', date: addDays(today, -7) },
  ];

  return (
    <Card>
      <Stack gap="md">
        <Inline gap="sm" wrap>
          {presets.map((preset) => (
            <Button
              key={preset.label}
              size="sm"
              variant={isSameDay(current, preset.date) ? 'primary' : 'secondary'}
              onClick={() => pick(preset.date)}
            >
              {preset.label}
            </Button>
          ))}
        </Inline>

        <Inline gap="sm" align="center" justify="space-between">
          <Button size="sm" variant="ghost" aria-label="Предыдущий месяц" onClick={() => shiftMonth(-1)}>
            ‹
          </Button>
          <Text weight="medium">{monthLabel}</Text>
          <Button size="sm" variant="ghost" aria-label="Следующий месяц" onClick={() => shiftMonth(1)}>
            ›
          </Button>
        </Inline>

        <div
          role="grid"
          aria-label={monthLabel}
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(7, 1fr)',
            gap: 'var(--jx-space-1)',
          }}
        >
          {weekdayNames.map((name) => (
            <Text key={name} size="sm" tone="muted" align="center">
              {name}
            </Text>
          ))}

          {cells.map((date, index) =>
            date ? (
              <Button
                key={date.toISOString()}
                size="sm"
                fullWidth
                variant={isSameDay(current, date) ? 'primary' : isSameDay(today, date) ? 'secondary' : 'ghost'}
                aria-pressed={isSameDay(current, date)}
                onClick={() => pick(date)}
              >
                {date.getDate()}
              </Button>
            ) : (
              <span key={`empty-${index}`} aria-hidden="true" />
            ),
          )}
        </div>
      </Stack>
    </Card>
  );
}

export default ReportDatePicker;

